-- indexes
CREATE INDEX idx_activity_log_actor ON public.activity_log USING btree (actor_id);
CREATE INDEX idx_activity_log_admin_actions ON public.activity_log USING btree (contributor_id, created_at DESC) WHERE (actor_role = 'admin'::text);
CREATE INDEX idx_activity_log_contributor ON public.activity_log USING btree (contributor_id, created_at DESC);
CREATE INDEX admin_actions_actor_idx ON public.admin_actions USING btree (actor_id, created_at DESC);
CREATE INDEX admin_actions_created_idx ON public.admin_actions USING btree (created_at DESC);
CREATE INDEX admin_actions_target_idx ON public.admin_actions USING btree (target_type, target_id);
CREATE INDEX analytics_daily_day_key_idx ON public.analytics_daily USING btree (day, metric_key);
CREATE INDEX analytics_daily_org_day_idx ON public.analytics_daily USING btree (org_id, day) WHERE (org_id IS NOT NULL);
CREATE UNIQUE INDEX analytics_daily_platform_wide_uniq ON public.analytics_daily USING btree (day, metric_key) WHERE (org_id IS NULL);
CREATE INDEX idx_broadcast_contributor ON public.broadcast_messages USING btree (contributor_id, created_at DESC);
CREATE INDEX idx_broadcast_entity ON public.broadcast_messages USING btree (entity_type, entity_id, created_at DESC) WHERE (deleted_at IS NULL);
CREATE INDEX comments_event_id_idx ON public.comments USING btree (event_id);
CREATE INDEX comments_user_id_idx ON public.comments USING btree (user_id);
CREATE UNIQUE INDEX contributor_access_requests_pending_unique ON public.contributor_access_requests USING btree (contributor_id, admin_id) WHERE ((status = 'pending'::text) AND (revoked_at IS NULL));
CREATE INDEX idx_car_admin ON public.contributor_access_requests USING btree (admin_id);
CREATE INDEX idx_car_contributor ON public.contributor_access_requests USING btree (contributor_id, status);
CREATE INDEX idx_analytics_contributor_date ON public.contributor_analytics USING btree (contributor_id, date DESC);
CREATE INDEX idx_analytics_entity ON public.contributor_analytics USING btree (entity_type, entity_id, date DESC) WHERE (entity_id IS NOT NULL);
CREATE UNIQUE INDEX contributor_applications_one_pending_per_user ON public.contributor_applications USING btree (user_id) WHERE (status = 'pending'::text);
CREATE INDEX contributor_applications_status_submitted_idx ON public.contributor_applications USING btree (status, submitted_at DESC);
CREATE INDEX contributor_applications_user_id_idx ON public.contributor_applications USING btree (user_id);
CREATE INDEX idx_drafts_contributor ON public.contributor_drafts USING btree (contributor_id, draft_type, created_at DESC);
CREATE INDEX idx_keywords_contributor ON public.contributor_keywords USING btree (contributor_id);
CREATE INDEX idx_keywords_text ON public.contributor_keywords USING gin (to_tsvector('english'::regconfig, keyword));
CREATE UNIQUE INDEX idx_keywords_unique_lower ON public.contributor_keywords USING btree (contributor_id, lower(keyword));
CREATE INDEX contributor_locations_profile_idx ON public.contributor_locations USING btree (profile_id, sort_order);
